package com.miniforce.controller;
import com.miniforce.dto.DiscussionDtos.*; import com.miniforce.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/discussions") public class DiscussionController {private final DiscussionService discussions;private final CurrentUser current;public DiscussionController(DiscussionService d,CurrentUser c){discussions=d;current=c;}@GetMapping List<DiscussionSummary> all(){return discussions.all();}@GetMapping("/{id}") DiscussionDetail get(@PathVariable Long id){return discussions.get(id);}@PostMapping ResponseEntity<DiscussionDetail> create(@Valid @RequestBody DiscussionRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(discussions.create(current.require(),r));}@PostMapping("/{id}/replies") ResponseEntity<ReplyResponse> reply(@PathVariable Long id,@Valid @RequestBody ReplyRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(discussions.reply(id,current.require(),r));}}
